const merged = { ...a, ...b };
const without = (({ id, ...rest }) => rest)(row);
const byId = Object.fromEntries(rows.map((r) => [r.id, r]));
const unique = [...new Set(list)];
const sorted = [...list].sort((a, b) => a - b);       // copy first
const last = list.at(-1);
const grouped = Object.groupBy(rows, (r) => r.type);    // ES2024
const sum = list.reduce((a, b) => a + b, 0);
const range = Array.from({ length: 5 }, (_, i) => i);   // [0,1,2,3,4]
const shuffled = list.toSorted(() => Math.random() - 0.5);
```

Errors and Exception Design:
One base class plus a stable code is all a boundary handler needs:

```js
class AppError extends Error {
  constructor(message, { code, status = 500, cause } = {}) {
    super(message, { cause });
    this.name = new.target.name;
    this.code = code ?? 'internal';
    this.status = status;
    Error.captureStackTrace?.(this, new.target);
  }
}

class NotFound extends AppError {
  constructor(what, id) { super(`${what} ${id} not found`, { code: 'not_found', status: 404 }); }
}
class ValidationFailed extends AppError {
  constructor(fields) { super('validation failed', { code: 'invalid', status: 422 }); this.fields = fields; }
}

try {
  throw new NotFound('order', 42);
} catch (err) {
  console.log(err instanceof AppError, err.code, err.status, err.message);
  // true not_found 404 order 42 not found
}
```

One handler maps every known error, and anything unknown becomes a safe 500:

```js
function toResponse(err) {
  if (err instanceof ValidationFailed) return { status: 422, body: { code: err.code, fields: err.fields } };
  if (err instanceof AppError) return { status: err.status, body: { code: err.code, message: err.message } };
  logError(err);                                   // full detail server-side only
  return { status: 500, body: { code: 'internal', message: 'something went wrong' } };
}
```

Errors as values for the expected cases, exceptions for the rest:

```js
const parseAge = (input) => {
  const n = Number(input);
  if (!Number.isInteger(n) || n < 0) return { ok: false, error: 'age must be a whole number >= 0' };
  return { ok: true, value: n };
};

const result = parseAge('x');
if (!result.ok) console.log(result.error);
else console.log(result.value);
```

Wrap at the boundary so the original stack survives: `new AppError('save failed', { cause: err })` keeps the cause chain readable without replacing the trace.

JSON and Serialization:
The `replacer` and `reviver` are the two hooks, and they are how you round-trip types JSON does not know:

```js
const state = { when: new Date(), count: 0n, missing: undefined, fn: () => {} };

const json = JSON.stringify(state, (key, value) => {
  if (typeof value === 'bigint') return { __bigint: value.toString() };
  if (value instanceof Date) return { __date: value.toISOString() };
  if (typeof value === 'function' || value === undefined) return undefined;
  return value;
});
console.log(json);

const back = JSON.parse(json, (key, value) => {
  if (value && typeof value === 'object') {
    if ('__bigint' in value) return BigInt(value.__bigint);
    if ('__date' in value) return new Date(value.__date);
  }
  return value;
});
console.log(back.when instanceof Date, back.count + 1n);
```

The traps: `undefined` and functions vanish silently, `NaN` and `Infinity` become `null`, a cyclic object throws, and property order is insertion order for strings but numeric keys are sorted first:

```js
console.log(JSON.stringify({ b: 1, 2: 'x', a: 2 }));   // {"2":"x","b":1,"a":2}
console.log(JSON.stringify([1, undefined, NaN]));      // [1,null,null]
console.log(JSON.stringify({ a: 1 }, null, 2));        // pretty, 2 spaces

try { const c = {}; c.self = c; JSON.stringify(c); }
catch (err) { console.log(err.name); }                 // TypeError
```

Newline-delimited JSON is the format for streams: one value per line, constant memory, and a corrupt line can be skipped instead of discarding the file:

```js
const lines = data.split('\n').filter(Boolean);
let parsed = 0;
for (const line of lines) {
  try { const row = JSON.parse(line); parsed++; }
  catch { console.warn('skipping a bad line'); }
}
console.log(parsed, 'of', lines.length);
```

Web Components:
A custom element is a class plus a tag name with a hyphen, and the lifecycle hooks are `connected`, `disconnected` and `attributeChanged`:

```js
class StarRating extends HTMLElement {
  static observedAttributes = ['value', 'max'];
  #value = 0;

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (name === 'value') this.#value = Number(newValue) || 0;
    this.#render();
  }

  connectedCallback() { this.#render(); }

  #render() {
    const max = Number(this.getAttribute('max')) || 5;
    this.shadowRoot.innerHTML = `
      <style>:host { display: inline-flex; gap: 2px } span { color: #f59e0b }</style>
      <span>${'\u2605'.repeat(this.#value)}</span><span>${'\u2606'.repeat(max - this.#value)}</span>
    `;
  }
}

customElements.define('star-rating', StarRating);
// <star-rating value="3" max="5"></star-rating>
```

Dispatch events upward instead of calling out, so the component has no knowledge of its user:

```js
this.dispatchEvent(new CustomEvent('rating:change', {
  detail: { value: this.#value },
  bubbles: true,
  composed: true,          // composed crosses the shadow boundary
}));
```

A `<template>` in the document keeps the markup out of JavaScript and is cloned once per instance:

```html
<template id="row">
  <li class="row"><span class="name"></span><button>x</button></li>
</template>
```

```js
const tpl = document.getElementById('row');
const node = tpl.content.cloneNode(true);
node.querySelector('.name').textContent = user.name;
list.append(node);
```

Shadow DOM scopes styles in and blocks selectors from outside; tokens cross the boundary through CSS custom properties, which is the intended escape hatch.

WebAssembly and Advanced Graphics:
Instantiating a module and calling an export is a few lines, and the imports object is the only bridge to JavaScript:

```js
const bytes = await (await fetch('/math.wasm')).arrayBuffer();

const { instance } = await WebAssembly.instantiate(bytes, {
  env: {
    log: (n) => console.log('from wasm:', n),
    memory: new WebAssembly.Memory({ initial: 1 }),
  },
});

const { add, fill } = instance.exports;
console.log(add(2, 3));
fill(0, 10, 7);                       // write 7 into the first 10 bytes
const view = new Uint8Array(instance.exports.memory.buffer);
console.log([...view.slice(0, 5)]);
```

Passing strings across the boundary is the awkward part: you write bytes into the module's memory and pass an offset and a length.

```js
const encoder = new TextEncoder();
const encoded = encoder.encode('hello');
const ptr = instance.exports.alloc(encoded.length);
new Uint8Array(instance.exports.memory.buffer, ptr, encoded.length).set(encoded);
instance.exports.handle(ptr, encoded.length);
```

Canvas animation belongs in `requestAnimationFrame`, and the cheap win is to draw once per frame rather than per event:

```js
const ctx = canvas.getContext('2d');
let t = 0;
function frame() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < 200; i++) {
    const a = t / 60 + i;
    const x = canvas.width / 2 + Math.cos(a) * (40 + i / 4);
    const y = canvas.height / 2 + Math.sin(a) * (40 + i / 4);
    ctx.fillStyle = `hsl(${(a * 57) % 360} 80% 60%)`;
    ctx.fillRect(x, y, 3, 3);
  }
  t++;
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
```

For 3D, WebGL and WebGPU are the APIs; the pattern is always the same — create buffers once, upload attribute data, compile a shader pair, then issue draw calls per frame and keep per-frame allocation near zero.

Decorators, Proposals and the Future:
Class decorators and method decorators receive the class or the method and return a replacement:

```js
function logged(original, context) {
  return function (...args) {
    console.log(`calling ${String(context.name)}(${args.length} args)`);
    const result = original.apply(this, args);
    console.log(`${String(context.name)} ->`, result);
    return result;
  };
}

class Cart {
  #items = [];
  @logged
  add(item) { this.#items.push(item); return this.#items.length; }
}

new Cart().add({ id: 1 });
// calling add(1 args)
// add -> 1
```

Decorators are still a proposal and the exact API has shifted, so keep them out of code you cannot easily change.

Stage-4 features that already work everywhere:

```js
const list = [3, 1, 2];
console.log(list.toSorted((a, b) => a - b), list);   // [1,2,3] [3,1,2]
console.log([1, 2, 3].toReversed());                 // [3, 2, 1]
console.log(Object.groupBy([1, 2, 3, 4], (n) => (n % 2 ? 'odd' : 'even')));
console.log([1, 2].with(0, 9));                      // [9, 2]
const { a, ...rest } = { a: 1, b: 2 };
console.log(rest);                                   // { b: 2 }
try { JSON.parse('{'); } catch { console.log('no binding needed'); }
```

The safest posture toward proposals is to feature-detect, not polyfill blindly:

```js
const groupBy = Object.groupBy ?? ((items, keyOf) => {
  const out = Object.create(null);
  for (const item of items) (out[keyOf(item)] ??= []).push(item);
  return out;
});
console.log(groupBy([1, 2], (n) => (n % 2 ? 'odd' : 'even')));
```

`using` and explicit resource management, `Temporal`, and pattern matching are the three to watch; each one removes a library rather than adding syntax you must learn.

Functions, Closures and this — Worked Ex:
Binding, borrowing and partial application are all the same mechanism:

```js
const base = { prefix: '>>', log(msg) { return `${this.prefix} ${msg}`; } };
const other = { prefix: '--' };
console.log(base.log('hi'));                 // >> hi
console.log(base.log.call(other, 'hi'));     // -- hi

const partial = (fn, ...preset) => (...rest) => fn(...preset, ...rest);
const warn = partial(base.log, 'WARN');
console.log(warn.call(base, 'disk full'));   // >> WARN disk full
```

`bind` is what makes a method safe to pass as a callback, and arrow functions are the other option:

```js
class Timer {
  ticks = 0;
  start() {
    this.handle = this.tick.bind(this);      // stable reference, needed to clear
    this.id = setInterval(this.handle, 1000);
  }
  tick() { this.ticks++; }
  stop() { clearInterval(this.id); }
}
```

Closures over `let` create a fresh binding per iteration; closures over `var` share one:

```js
const make = (n) => () => n;
console.log([1, 2, 3].map(make).map((f) => f()));    // [1, 2, 3]

const counters = [];
for (let i = 0; i < 3; i++) {
  counters.push({ get: () => i, set: (v) => { i = v; } });
}
counters[1].set(99);
console.log(counters.map((c) => c.get()));           // [0, 99, 2]
```

Objects, Prototypes and Classes — Worked:
Class fields live on the instance; prototype methods are shared, and `super` looks them up on the prototype chain rather than on the instance:

```js
class Base {
  kind = 'base';
  describe() { return `kind=${this.kind}`; }
}
class Child extends Base {
  kind = 'child';
  describe() { return `child of ${super.describe()}`; }
}
const c = new Child();
console.log(c.describe());                    // child of kind=child
console.log(Object.hasOwn(c, 'kind'));        // true — a field, not a method
console.log(Object.hasOwn(c, 'describe'));    // false — inherited
```

Arrow fields capture the instance, which is why they work as event handlers and methods are often the wrong choice there:

```js
class Button {
  label = 'save';
  onClick = () => this.label;                 // bound to the instance
  onClickMethod() { return this.label; }      // depends on the receiver
}
const b = new Button();
const { onClick, onClickMethod } = b;
console.log(onClick());                       // 'save'
console.log(onClickMethod());                 // TypeError: this is undefined
```

Class identity is per definition, so hot-reloading two definitions creates two incompatible types:

```js
const A = class {};
console.log(new A() instanceof A);            // true
console.log(Object.getPrototypeOf(A.prototype) === Object.prototype);   // true
console.log(A.name);                          // 'A' for a named class expression
```
